<span class="line"><span style="color:#B392F0;">curl</span><span style="color:#79B8FF;"> -C</span><span style="color:#9ECBFF;"> -</span><span style="color:#79B8FF;"> -O</span><span style="color:#9ECBFF;"> http://example.com/file.zip</span></span>
